        if text.kind == kind::_BLANKLINE { return Some(TriviaNode::Blankline); }
        if text.kind == kind::_DOUBLE_BLANKLINE { return Some(TriviaNode::DoubleBlankline); }
        if text.kind == kind::_INDENT { return Some(TriviaNode::Indent); }
